package in.com.rays.constructor;

public class Person {

	private String name;
	private int phoneNo;

	public Person() {
		// TODO Auto-generated constructor stub
	}

	public Person(String name, int phoneNo) {
		this.name = name;
		this.phoneNo = phoneNo;
	}

	public String getName() {
		return name;
	}

	public int getPhoneNo() {
		return phoneNo;
	}

}
